SELECT customers.country, customers.segment, MIN(transactions.amount) AS min_amount, MAX(transactions.amount) - MIN(transactions.amount) AS amount_range FROM transactions INNER JOIN accounts ON transactions.account_id = accounts.id INNER JOIN customers ON accounts.customer_id = customers.id WHERE customers.signup_date > '2023-09-10' GROUP BY customers.country, customers.segment ORDER BY amount_range DESC, country, segment LIMIT 20
